// The handler `@sveltejs/adapter-cloudflare` emits for SvelteKit's SSR + routes.
// Resolves after the first `vite build`; `lunora dev` proxies SvelteKit's dev
// server, so it's only needed for the build.
// `@ts-ignore`, not `@ts-expect-error`: whether this specifier resolves depends on
// whether a build has run. Before the first `vite build` it does not (TS2307);
// after one it does, and `@ts-expect-error` then reports itself as unused (TS2578).
// Only `@ts-ignore` is correct in both states.
// @ts-ignore -- generated by `@sveltejs/adapter-cloudflare` at build time
import svelteKitWorker from "../.svelte-kit/cloudflare/_worker.js";

import { lunora } from "../lunora/app";

/**
 * Single-worker entry (PLAN4 §3, class-B), finishing the app builder defined
 * in `lunora/app.ts`. `.buildFrameworkWorker(svelteKitWorker)` folds the
 * adapter-emitted SvelteKit handler in as the framework host: the reserved
 * `/_lunora/{rpc,ws,admin}` endpoints route into Lunora (forwarded to the
 * `SHARD` Durable Object) and everything else — pages, endpoints, same-origin
 * `+page.ts` loaders — delegates to SvelteKit. One worker, one deploy, one
 * `ShardDO` namespace. Configure the app (`.auth()`, a shard gate, …) in
 * `lunora/app.ts`, never here, so the dev entry gets the same app.
 */
const app = lunora.buildFrameworkWorker(svelteKitWorker);

export const ShardDO = app.ShardDO;
// Tracks which shards hold `.shardBy()` rows, for cross-shard export / CDC sync.
export { ShardRegistryDO } from "../lunora/_generated/shardRegistry.js";
export default app;
